cat > /tmp/probe/cna3_pred.awk <<'AWK'
function pred(w,  n,c,p) {
  n=length(w)
  c=substr(w,n,1); p=(n>1)?substr(w,n-1,1):""
  if (c=="y" && p!="" && p!~/[aeiou]/) return substr(w,1,n-1) "ies"
  if (substr(w,n-1,2)=="es") return w
  if (c=="s" || substr(w,n-1,2)=="ch" || substr(w,n-1,2)=="sh") return w "es"
  return w "s"
}
BEGIN{FS="\t"}
{ e=pred(tolower($1)); if ($2!=e) printf "%s\t%s\t(pred %s)\n", $1,$2,e }
AWK
awk -f /tmp/probe/cna3_pred.awk /tmp/probe/data/cna3_a.out.tsv
